def transform(grid):
    n = len(grid) // 3
    out = []
    for br in range(n):
        row = []
        for bc in range(n):
            vals = [grid[r][c] for r in range(3*br, 3*br+3) for c in range(3*bc, 3*bc+3) if grid[r][c] != 5]
            row.append(Counter(vals).most_common(1)[0][0])
        out.append(row)
    return out
